-- Isolated Cloud Save V1 proposed SQLite schema. Not deployed to D1.
PRAGMA foreign_keys=ON;
CREATE TABLE accounts(id TEXT PRIMARY KEY,auth_subject TEXT UNIQUE NOT NULL,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','disabled')));
CREATE TABLE characters(id TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES accounts(id),slot_index INTEGER NOT NULL CHECK(slot_index BETWEEN 0 AND 7),save_version INTEGER NOT NULL DEFAULT 0,gold INTEGER NOT NULL DEFAULT 0 CHECK(gold>=0),state_json TEXT NOT NULL DEFAULT '{}',UNIQUE(account_id,slot_index),UNIQUE(id,account_id));
CREATE TABLE item_stacks(account_id TEXT NOT NULL REFERENCES accounts(id),container_id TEXT NOT NULL,item_id TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),PRIMARY KEY(account_id,container_id,item_id));
CREATE TABLE pets(id TEXT PRIMARY KEY,account_id TEXT NOT NULL,character_id TEXT NOT NULL,state_json TEXT NOT NULL,UNIQUE(id,account_id),FOREIGN KEY(character_id,account_id) REFERENCES characters(id,account_id));
CREATE TABLE equipment(uid TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES accounts(id),location TEXT NOT NULL CHECK(location IN ('bag','equipped','warehouse','pet_equipped')),character_id TEXT,pet_id TEXT,item_id TEXT NOT NULL,state_json TEXT NOT NULL,CHECK((location='warehouse' AND character_id IS NULL AND pet_id IS NULL) OR (location IN('bag','equipped') AND character_id IS NOT NULL AND pet_id IS NULL) OR (location='pet_equipped' AND character_id IS NOT NULL AND pet_id IS NOT NULL)),FOREIGN KEY(character_id,account_id) REFERENCES characters(id,account_id),FOREIGN KEY(pet_id,account_id) REFERENCES pets(id,account_id));
CREATE TABLE offline_sessions(id TEXT PRIMARY KEY,account_id TEXT NOT NULL,character_id TEXT NOT NULL,start_ms INTEGER NOT NULL,end_ms INTEGER NOT NULL,cursor INTEGER NOT NULL DEFAULT 0 CHECK(cursor>=0),seed TEXT NOT NULL,state_json TEXT NOT NULL,result_json TEXT,status TEXT NOT NULL CHECK(status IN ('pending','settling','ready','claimed','failed')),CHECK(end_ms>=start_ms AND end_ms-start_ms<=86400000),FOREIGN KEY(character_id,account_id) REFERENCES characters(id,account_id));
CREATE UNIQUE INDEX one_open_offline_session ON offline_sessions(character_id) WHERE status IN ('pending','settling','ready');
CREATE TABLE operation_ledger(account_id TEXT NOT NULL,request_key TEXT NOT NULL,request_hash TEXT NOT NULL,kind TEXT NOT NULL,result_json TEXT NOT NULL,PRIMARY KEY(account_id,request_key),FOREIGN KEY(account_id) REFERENCES accounts(id));
